"""Implementation of Taplo's toml-test decoder output format."""
import datetime
import ast
import json
import re
from typing import Any


def _encode(value: Any, dates: list[str]) -> Any:
    if isinstance(value, dict):
        return {key: _encode(item, dates) for key, item in value.items()}
    if isinstance(value, list):
        return [_encode(item, dates) for item in value]
    if isinstance(value, bool):
        return {"type": "bool", "value": "true" if value else "false"}
    if isinstance(value, int):
        return {"type": "integer", "value": str(value)}
    if isinstance(value, float):
        # Rust's float display keeps integral floats distinguishable.
        rendered = repr(value)
        if "e" not in rendered.lower() and "." not in rendered:
            rendered += ".0"
        return {"type": "float", "value": rendered}
    if isinstance(value, str):
        return {"type": "string", "value": value}
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        raw = dates.pop(0) if dates else value.isoformat()
        return {"type": "datetime", "value": json.dumps(raw, ensure_ascii=False)}
    return value


def decode(source: str) -> str:
    """Parse TOML and return its compact toml-test JSON representation."""
    parsed = _parse(source)
    # tomllib normalizes offsets (notably Z into +00:00); preserve TOML's
    # original date/time spelling for the tagged string representation.
    dt_re = re.compile(r"(?<![\w\"'])\d{4}-\d\d-\d\d(?:[Tt ]\d\d:\d\d:\d\d(?:\.\d+)?(?:[Zz]|[+-]\d\d:\d\d)?|\d\d:\d\d:\d\d(?:\.\d+)?)(?![\w'])")
    dates = [m.group(0) for m in dt_re.finditer(source)]
    return json.dumps(_encode(parsed, dates), ensure_ascii=False, separators=(",", ":"))


def _parse(source: str) -> dict:
    """Small TOML parser for Python 3.10, where tomllib is not available."""
    root: dict = {}
    table = root
    array_table: list | None = None
    pending = ""
    for raw in source.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        pending = (pending + " " + line).strip() if pending else line
        if _unclosed(pending):
            continue
        line, pending = pending, ""
        if line.startswith("[[") and line.endswith("]]" ):
            path = [x.strip().strip('"\'') for x in line[2:-2].split('.')]
            table = root
            for part in path[:-1]:
                table = table.setdefault(part, {})
            array_table = table.setdefault(path[-1], [])
            item = {}
            array_table.append(item)
            table = item
            continue
        if line.startswith("[") and line.endswith("]"):
            path = [x.strip().strip('"\'') for x in line[1:-1].split('.')]
            table = root
            for part in path:
                next_table = table.setdefault(part, {})
                if isinstance(next_table, list):
                    next_table = next_table[-1]
                table = next_table
            continue
        eq = _find_eq(line)
        if eq < 0:
            continue
        key = line[:eq].strip().strip('"\'')
        val = _value(_strip_comment(line[eq + 1:].strip()))
        table[key] = val
    return root


def _unclosed(s: str) -> bool:
    q = None; esc = False; depth = 0
    for c in s:
        if q:
            if esc: esc = False
            elif c == "\\" and q == '"': esc = True
            elif c == q: q = None
        elif c in "\"'": q = c
        elif c in "[{": depth += 1
        elif c in "]}": depth -= 1
    return bool(q or depth > 0)


def _find_eq(s: str) -> int:
    q = None; esc = False; depth = 0
    for i, c in enumerate(s):
        if q:
            if esc: esc = False
            elif c == "\\" and q == '"': esc = True
            elif c == q: q = None
        elif c in "\"'": q = c
        elif c in "[{": depth += 1
        elif c in "]}": depth -= 1
        elif c == "=" and depth == 0: return i
    return -1


def _strip_comment(s: str) -> str:
    q = None; esc = False
    for i, c in enumerate(s):
        if q:
            if esc: esc = False
            elif c == "\\" and q == '"': esc = True
            elif c == q: q = None
        elif c in "\"'": q = c
        elif c == "#": return s[:i].strip()
    return s


def _value(s: str) -> Any:
    s = s.strip()
    if s.startswith("[") and s.endswith("]"):
        return [_value(x) for x in _split(s[1:-1]) if x.strip()]
    if s.startswith("{") and s.endswith("}"):
        out = {}
        for entry in _split(s[1:-1]):
            i = _find_eq(entry)
            if i >= 0: out[entry[:i].strip().strip('"\'')] = _value(entry[i+1:])
        return out
    if s in ("true", "false"): return s == "true"
    if re.match(r"^\d{4}-\d\d-\d\d(?:[Tt ]|$)|^\d\d:\d\d:\d\d", s):
        try: return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")) if "T" in s or "t" in s or " " in s else datetime.date.fromisoformat(s)
        except ValueError: return datetime.time.fromisoformat(s)
    normalized = s.replace("_", "")
    try:
        if any(c in normalized for c in ".eE"): return float(normalized)
        return int(normalized, 0) if normalized.lower().startswith(("0x", "0o", "0b")) else int(normalized)
    except ValueError: pass
    try: return ast.literal_eval(s)
    except Exception: return s.strip('"\'')


def _split(s: str) -> list[str]:
    out=[]; start=0; q=None; esc=False; depth=0
    for i,c in enumerate(s):
        if q:
            if esc: esc=False
            elif c == "\\" and q == '"': esc=True
            elif c == q: q=None
        elif c in "\"'": q=c
        elif c in "[{": depth += 1
        elif c in "]}": depth -= 1
        elif c == "," and depth == 0: out.append(s[start:i]); start=i+1
    out.append(s[start:]); return out

