def _toml_document(document, source=""):
    """Serialize a complete document, retaining insertion order and table form."""
    chunks = []
    root_values = [(k, v) for k, v in document.items() if not isinstance(v, dict)
                   and not (isinstance(v, list) and v and all(isinstance(x, dict) for x in v))
                   or _inline_root(source, k)]
    if root_values:
        chunks.append("\n".join(_toml_entry(k, v, source) for k, v in root_values))

    def emit_table(name, table):
        lines = [f"[{_toml_path(name)}]"] if name else []
        children = []
        for key, value in table.items():
            if isinstance(value, dict):
                children.append((key, value))
            elif isinstance(value, list) and value and all(isinstance(x, dict) for x in value):
                children.append((key, value))
            else:
                lines.append(_toml_entry(key, value, source))
        if lines:
            chunks.append("\n".join(lines))
        for key, value in children:
            path = tuple(name) + (str(key),)
            if isinstance(value, list):
                for table_item in value:
                    emit_array_table(path, table_item)
            else:
                emit_table(path, value)

    def emit_array_table(name, table):
        lines = [f"[[{_toml_path(name)}]]"]
        children = []
        for key, value in table.items():
            if isinstance(value, dict): children.append((key, value))
            elif isinstance(value, list) and value and all(isinstance(x, dict) for x in value): children.append((key, value))
            else: lines.append(_toml_entry(key, value, source))
        chunks.append("\n".join(lines))
        for key, value in children:
            path = tuple(name) + (str(key),)
            if isinstance(value, list):
                for item in value: emit_array_table(path, item)
            else: emit_table(path, value)

    for key, value in document.items():
        if isinstance(value, dict) and not _inline_root(source, key): emit_table((str(key),), value)
        elif isinstance(value, list) and value and all(isinstance(x, dict) for x in value) and not _inline_root(source, key):
            for item in value: emit_array_table((str(key),), item)
    return "\n".join(chunks) + ("\n" if chunks else "")



def _is_inline_table(source, pattern):
    if not pattern:
        return False
    parts = _path_parts(pattern)
    key = parts[-1] if parts else pattern
    if not key.endswith("]"):
        spellings = (re.escape(key), re.escape(json.dumps(key, ensure_ascii=False)),
                     re.escape("'" + key + "'"))
        for spelling in spellings:
            if re.search(r"(?m)(?:^|[,{]\s*)" + spelling + r"\s*=\s*\{", source):
                return True
    # A table selected by array index retains inline-table formatting when
    # its containing value was written as an inline array of tables.
    for index, part in enumerate(parts):
        if part.isdigit() and index:
            parent = parts[index - 1]
            assignment = re.search(r"(?m)^\s*" + re.escape(parent) + r"\s*=\s*\[", source)
            if assignment:
                depth = 1; quote = None; escaped = False; comment = False
                for char in source[assignment.end():]:
                    if comment:
                        if char == "\n": comment = False
                        continue
                    if quote:
                        if escaped: escaped = False
                        elif char == "\\" and quote == '"': escaped = True
                        elif char == quote: quote = None
                    elif char in ('"', "'"): quote = char
                    elif char == "#":
                        comment = True
                    elif char == "[": depth += 1
                    elif char == "]":
                        depth -= 1
                        if depth == 0: break
                    elif char == "{": return True
    return False


def _table_document(value, source, base_parts=(), relative_headers=True):
    """Serialize a selected document/table while retaining explicit tables."""
    if not isinstance(value, dict):
        return _toml(value) + "\n"
    lines = []
    child_tables = []
    arrays_of_tables = []
    for key, child in value.items():
        path = tuple(base_parts) + (str(key),)
        dotted = _toml_path(path)
        table_header = re.search(r"(?m)^\s*\[\s*" + re.escape(dotted) + r"\s*\]\s*(?:#.*)?$", source)
        array_header = re.search(r"(?m)^\s*\[\[\s*" + re.escape(dotted) + r"\s*\]\]\s*(?:#.*)?$", source)
        if isinstance(child, dict) and table_header:
            child_tables.append((key, child, path))
        elif isinstance(child, list) and child and all(isinstance(x, dict) for x in child) and array_header:
            arrays_of_tables.append((key, child, path))
        else:
            lines.append(_toml_entry(key, child, source))
    for key, child, path in child_tables:
        suffix = _toml_path(path[len(base_parts):] if relative_headers else path)
        header = f"[{suffix}]"
        if lines and re.search(r"=\s*\{.*\}$", lines[-1]):
            lines[-1] += header
        else:
            lines.append(header)
        lines.extend(_table_document(child, source, path, relative_headers).rstrip("\n").splitlines())
    for key, children, path in arrays_of_tables:
        suffix = _toml_path(path[len(base_parts):] if relative_headers else path)
        for child in children:
            lines.append(f"[[{suffix}]]")
            lines.extend(_table_document(child, source, path, relative_headers).rstrip("\n").splitlines())
    inline_keys = [key for key, child in value.items() if isinstance(child, dict) and _inline_root(source, str(key))]
    if lines and len(inline_keys) == len(value) and inline_keys:
        return "".join(lines) + "\n"
    return "\n".join(lines) + ("\n" if lines else "")


def _text(value, separator="\n", source=""):
    if isinstance(value, TemporalValue): return value.canonical
    if isinstance(value, bool): return str(value).lower()
    if isinstance(value, FloatValue):
        try:
            return format(Decimal(str(value).replace("_", "")), "f").rstrip("0").rstrip(".") if "." in str(value) else format(Decimal(str(value).replace("_", "")), "f")
        except InvalidOperation:
            return str(value)
    if isinstance(value, str): return value

    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return _temporal(value, source)

    if isinstance(value, int): return str(value)
    if isinstance(value, float):
        if math.isnan(value): return "NaN"
        if math.isinf(value): return "-inf" if value < 0 else "inf"
        try:
            rendered = format(Decimal(str(value)), "f")
            if "." in rendered:
                rendered = rendered.rstrip("0").rstrip(".")
            return rendered
        except InvalidOperation:
            return str(value)
    if isinstance(value, list):
        flattened = []
        def append_scalars(item):
            if isinstance(item, dict):
                raise ValueError
            if isinstance(item, list):
                for child in item:
                    append_scalars(child)
            else:
                flattened.append(_text(item, separator, source))
        append_scalars(value)
        return separator.join(flattened)
    raise ValueError


def _json_value(value, source=""):
    if isinstance(value, dict):
        return {key: _json_value(child, source) for key, child in value.items()}
    if isinstance(value, list):

        return [_json_value(child, source) for child in value]
    if isinstance(value, FloatValue):
        number = float(str(value).replace("_", ""))
        return number if math.isfinite(number) else None
    if isinstance(value, float) and not math.isfinite(value):
        return None
    if isinstance(value, TemporalValue):
        return value.canonical
    if isinstance(value, (datetime.datetime, datetime.date, datetime.time)):
        return _temporal(value, source)

    return value


def _normalize_json_exponents(text):
    """Match serde_json's compact exponent spelling without touching strings."""
    out = []
    i = 0
    in_string = False
    escaped = False
    number = re.compile(r"-?\d+(?:\.\d+)?[eE][+-]?\d+")
    while i < len(text):
        char = text[i]
        if in_string:
            out.append(char)
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            i += 1
        elif char == '"':
            in_string = True
            out.append(char)
            i += 1
        elif char == "-" or char.isdigit():
            match = number.match(text, i)
            if match:
                token = match.group(0)
                token = re.sub(r"[eE]\+?(-?)0*(\d+)$", r"e\1\2", token)
                out.append(token)
                i = match.end()
            else:
                out.append(char)
                i += 1
        else:
            out.append(char)
            i += 1
    return "".join(out)


